"""Snap span times to a fixed step and label the result."""

import typing

from hourglass import errors, models, parsing


def _snap(minutes: int, step: int) -> int:
    return (2 * minutes + step) // (2 * step) * step


def round_spans(
    spans: typing.Iterable[models.Span], step: int
) -> typing.List[str]:
    """Label each span like 09:00-17:15 (8h 15m), times snapped to step."""
    if step <= 0 or 60 % step:
        raise errors.ProjectError(f"bad rounding step: {step}")
    labels = []
    for span in spans:
        start = _snap(span.start, step)
        end = _snap(span.end, step)
        if start >= end:
            raise errors.ProjectError(
                f"span vanishes at step {step}: "
                f"{parsing.format_span(span)}"
            )
        hours, minutes = divmod(end - start, 60)
        labels.append(
            f"{parsing.format_clock(start)}-"
            f"{parsing.format_clock(end)} ({hours}h {minutes}m)"
        )
    return labels
