cat > qa/test_rounding.py <<'EOF'
import unittest

from hourglass import errors, models, parsing, rounding


def spans(*texts):
    return [parsing.parse_span(text) for text in texts]


class RoundingTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        result = rounding.round_spans(spans("09:03-17:11"), 15)
        self.assertEqual(result, ["09:00-17:15 (8h 15m)"])

    def test_one_label_per_span(self):
        result = rounding.round_spans(
            spans("08:50-12:00", "13:00-17:20"), 30
        )
        self.assertEqual(
            result,
            ["09:00-12:00 (3h 0m)", "13:00-17:30 (4h 30m)"],
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(errors.ProjectError):
                rounding.round_spans(spans("09:00-10:00"), step)

    def test_vanishing_span_raises(self):
        with self.assertRaises(errors.ProjectError):
            rounding.round_spans([models.Span(61, 65)], 30)


if __name__ == "__main__":
    unittest.main()
